uses(RefreshTenantDatabase::class);
beforeEach(function(){config(['tenancy.domain'=>'bizismart.test']);$this->context=app(TenantContext::class);$plan=Plan::create(['code'=>'incentive','name'=>'Incentive','price_monthly'=>0,'limits'=>['tills'=>10,'products'=>100],'features'=>[]]);foreach(['alpha','beta']as$label){$b=Business::create(['name'=>$label,'subdomain'=>$label,'plan_id'=>$plan->id,'owner_phone'=>'0700000001','vat_rate'=>0]);$this->{$label}=$b;$this->context->run($b,function()use($label){app(StaffRoleService::class)->provision();$branch=Branch::create(['name'=>'Main']);$this->{$label.'Branch'}=$branch;$device=Device::create(['device_uid'=>'incentive','name'=>'Incentive','status'=>'approved']);foreach(['owner','cashier','manager','stockkeeper']as$i=>$role){$u=User::create(['name'=>$role,'phone'=>'071000000'.$i,'pin_hash'=>'1234','must_change_pin'=>false,'branch_id'=>$branch->id]);app(StaffRoleService::class)->assign($u,$role);if($role==='owner'){$u->totp_secret='JBSWY3DPEHPK3PXP';$u->totp_confirmed_at=now();$u->save();}$token=$u->createToken('test',['*'],now()->addDay());$token->accessToken->device_id=$device->id;$token->accessToken->save();$this->{$label.ucfirst($role)}=$u->withAccessToken($token->accessToken);$this->{$label.ucfirst($role).'Token'}=$token->plainTextToken;}$p=Product::create(['name'=>'Item','quantity_type'=>'counted','unit'=>'item','selling_price'=>1000,'buying_price'=>100,'reorder_level_atoms'=>0,'is_active'=>true]);$this->{$label.'Product'}=$p;app(StockService::class)->receive($this->{$label.'Stockkeeper'},$p,['operation_id'=>(string)Str::uuid(),'batch_number'=>'OPEN','qty'=>'100','cost_price'=>100,'expiry_date'=>null]);$this->{$label.'Customer'}=Customer::create(['name'=>'Asha','credit_limit'=>100000])->fresh();$this->{$label.'Till'}=app(TillService::class)->open($this->{$label.'Cashier'},['operation_id'=>(string)Str::uuid(),'branch_id'=>$branch->publicId(),'opening_float'=>20000])['till'];});}$this->withToken($this->alphaOwnerToken);});
afterEach(function(){$this->context->clear();$this->travelBack();IncentiveEntry::flushEventListeners();\Illuminate\Database\Eloquent\Model::clearBootedModels();});
function incentivesUrl(string $path='',string $shop='alpha'):string{return 'http://'.$shop.'.bizismart.test/api/v1'.$path;}
it('never decodes an exact reserved catalogue barcode as weight and isolates reservations by tenant',function(){
 $label='2200123007506';$profile=['prefix'=>'22','product_start'=>2,'product_length'=>5,'weight_start'=>7,'weight_length'=>5];
 foreach(['alpha','beta']as$shop){$this->context->run($this->{$shop},function()use($shop,$label){Product::create(['name'=>'Scale rice','barcode'=>'00123','quantity_type'=>'weight','unit'=>'kg','selling_price'=>4000,'buying_price'=>3000,'reorder_level_atoms'=>0,'is_active'=>true]);if($shop==='alpha'){$this->alphaProduct->update(['barcode'=>$label]);\App\Models\ProductBarcode::create(['product_id'=>$this->alphaProduct->id,'barcode'=>$label]);}});$this->withToken($this->{$shop.'OwnerToken'})->postJson(incentivesUrl('/scales/profile',$shop),['operation_id'=>(string)Str::uuid(),'profile'=>$profile])->assertOk();}
 $this->withToken($this->alphaCashierToken)->postJson(incentivesUrl('/scales/decode'),['label'=>$label])->assertStatus(409)->assertJsonPath('error.code','REGISTERED_BARCODE');$this->context->run($this->alpha,fn()=>$this->alphaProduct->update(['is_active'=>false]));$this->postJson(incentivesUrl('/scales/decode'),['label'=>$label])->assertStatus(409)->assertJsonPath('error.code','REGISTERED_BARCODE');$this->withToken($this->betaCashierToken)->postJson(incentivesUrl('/scales/decode','beta'),['label'=>$label])->assertOk()->assertJsonPath('data.qty','0.75');$this->context->run($this->alpha,fn()=>expect(ProductBatch::sum('qty_remaining_atoms'))->toBe('100'));
});
it('disables future earning terms without rewriting captured credit collection and refund entitlements',function(){
 configureEarning($this);$credit=incentiveSale($this,'1',1000);$this->context->run($this->alpha,function(){ $business=Business::findOrFail($this->alpha->id);$business->settings=[...($business->settings??[]),'feature_overrides'=>['loyalty'=>false,'commissions'=>false]];$business->save(); });
 incentiveSale($this);$this->context->run($this->alpha,function(){ $accounts=IncentiveAccount::orderBy('id')->get();expect($accounts[0]->loyalty_tsh_per_point)->toBe(100)->and($accounts[0]->commission_basis_points)->toBe(1000)->and($accounts[1]->loyalty_tsh_per_point)->toBeNull()->and($accounts[1]->commission_basis_points)->toBeNull();expect(app(IncentiveService::class)->loyalty($this->alphaCustomer)['points'])->toBe(0); });
 $this->withToken($this->alphaCashierToken);$body=['till_id'=>$this->alphaTill['id'],'method'=>'cash','amount'=>1000,'allocations'=>[['sale_id'=>$credit['id'],'amount'=>1000]]];$url=incentivesUrl('/customers/'.$this->alphaCustomer->publicId().'/payments');$review=$this->postJson($url.'/preview',$body)->assertOk()->json('data.review_hash');$this->withHeader('Idempotency-Key',(string)Str::uuid())->postJson($url,[...$body,'review_hash'=>$review])->assertCreated();
 $this->context->run($this->alpha,function(){expect(app(IncentiveService::class)->loyalty($this->alphaCustomer)['points'])->toBe(10);expect(app(IncentiveService::class)->commission($this->alphaCashier)['earned'])->toBe(100);});
 incentiveReturn($this,$credit);$this->context->run($this->alpha,function(){expect(app(IncentiveService::class)->loyalty($this->alphaCustomer)['points'])->toBe(0);expect(app(IncentiveService::class)->commission($this->alphaCashier)['earned'])->toBe(0);});
});
it('issues revocable opaque loyalty cards with actor device retries and tenant isolation',function(){
 $url=incentivesUrl('/customers/'.$this->alphaCustomer->publicId().'/loyalty-card');$body=['operation_id'=>(string)Str::uuid()];$first=$this->postJson($url,$body)->assertCreated()->json('data.card');expect($first['token'])->toMatch('/^BSL:[a-f0-9]{32}$/');$this->postJson($url,$body)->assertOk()->assertJsonPath('data.card.token',$first['token'])->assertJsonPath('data.replayed',true);$this->withToken($this->alphaCashierToken)->postJson(incentivesUrl('/loyalty-cards/resolve'),['token'=>$first['token']])->assertOk()->assertJsonPath('data.id',$this->alphaCustomer->publicId());$this->postJson($url,$body)->assertStatus(409);$this->withToken($this->betaOwnerToken)->postJson(incentivesUrl('/loyalty-cards/resolve','beta'),['token'=>$first['token']])->assertNotFound();$this->withToken($this->alphaOwnerToken)->postJson($url,['operation_id'=>(string)Str::uuid()])->assertCreated();$this->postJson(incentivesUrl('/loyalty-cards/resolve'),['token'=>$first['token']])->assertNotFound();$this->postJson($url,$body)->assertOk()->assertJsonPath('data.card.active',false)->assertJsonPath('data.card.token',null);$this->context->run($this->alpha,function()use($first){expect(DB::table('loyalty_cards')->where('business_id',$this->alpha->id)->first()->token)->not->toBe($first['token']);});$this->withToken($this->alphaStockkeeperToken)->getJson($url)->assertForbidden();
});
it('ranks net commission with shared ties and owner permissions without crossing tenants',function(){
 configureEarning($this);incentiveSale($this,'2');$this->context->run($this->alpha,function(){$account=IncentiveAccount::first();IncentiveEntry::create(['incentive_account_id'=>$account->id,'cashier_id'=>$this->alphaManager->id,'customer_id'=>null,'event_key'=>'test:manager','event_type'=>'sale','paid_net_value'=>2000,'points_total'=>0,'commission_total'=>200,'points_delta'=>0,'commission_delta'=>200]);});$url=incentivesUrl('/incentives/leaderboard');$rows=$this->withToken($this->alphaOwnerToken)->getJson($url)->assertOk()->json('data.leaderboard');expect(array_column($rows,'rank'))->toBe([1,1])->and(array_column($rows,'earned'))->toBe([200,200]);$this->withToken($this->alphaManagerToken)->getJson($url)->assertForbidden();$this->withToken($this->betaOwnerToken)->getJson(incentivesUrl('/incentives/leaderboard','beta'))->assertOk()->assertJsonPath('meta.total',0);
});
it('configures and decodes exact weight labels without changing stock or accepting costs',function(){
 $profile=['prefix'=>'22','product_start'=>2,'product_length'=>5,'weight_start'=>7,'weight_length'=>5];$this->context->run($this->alpha,function(){Product::create(['name'=>'Rice','barcode'=>'00123','quantity_type'=>'weight','unit'=>'kg','selling_price'=>1000,'buying_price'=>100,'reorder_level_atoms'=>0,'is_active'=>true]);});$body=['operation_id'=>(string)Str::uuid(),'profile'=>$profile];$this->postJson(incentivesUrl('/scales/profile'),['operation_id'=>(string)Str::uuid(),'profile'=>[]])->assertStatus(422);$this->postJson(incentivesUrl('/scales/profile'),$body)->assertOk();$this->postJson(incentivesUrl('/scales/profile'),$body)->assertOk()->assertJsonPath('data.replayed',true);$this->postJson(incentivesUrl('/scales/profile'),[...$body,'profile'=>null])->assertStatus(409);$sum=0;$digits='220012300750';for($i=0;$i<12;$i++)$sum+=(int)$digits[$i]*($i%2===0?1:3);$label=$digits.((10-$sum%10)%10);$this->withToken($this->alphaCashierToken)->postJson(incentivesUrl('/scales/decode'),['label'=>$label])->assertOk()->assertJsonPath('data.qty','0.75')->assertJsonPath('data.product.barcode','00123')->assertJsonMissingPath('data.product.buying_price');$this->postJson(incentivesUrl('/scales/profile'),['operation_id'=>(string)Str::uuid(),'profile'=>null])->assertForbidden();$this->withToken($this->betaCashierToken)->postJson(incentivesUrl('/scales/decode','beta'),['label'=>$label])->assertStatus(409)->assertJsonPath('error.code','SCALE_NOT_CONFIGURED');$this->withToken($this->alphaOwnerToken)->postJson(incentivesUrl('/scales/profile'),['operation_id'=>(string)Str::uuid(),'profile'=>null])->assertOk();$this->postJson(incentivesUrl('/scales/decode'),['label'=>$label])->assertStatus(409);$this->context->run($this->alpha,function(){expect(ProductBatch::sum('qty_remaining_atoms'))->toBe('100');});
});
function configureEarning($t,int $unit=100,int $bps=1000,int $value=100):array{$t->withToken($t->alphaOwnerToken);$body=['operation_id'=>(string)Str::uuid(),'loyalty_tsh_per_point'=>$unit,'loyalty_point_value'=>$value,'commission_basis_points'=>$bps,'reason'=>'Owner configured'];$review=$t->postJson(incentivesUrl('/incentives/configuration/preview'),$body)->assertOk()->json('data.review_hash');$t->postJson(incentivesUrl('/incentives/configuration'),[...$body,'review_hash'=>$review])->assertCreated();return [...$body,'review_hash'=>$review];}
function incentiveSale($t,string $qty='1',int $credit=0,int $points=0):array{$t->withToken($t->alphaCashierToken);$body=['branch_id'=>$t->alphaBranch->publicId(),'till_id'=>$t->alphaTill['id'],'customer_id'=>$t->alphaCustomer->publicId(),'credit_amount'=>$credit,'items'=>[['product_id'=>$t->alphaProduct->publicId(),'qty'=>$qty]]];if($points){$body['loyalty_points']=$points;$body['discount_reason']='Customer point redemption';}$review=$t->postJson(incentivesUrl('/sales/preview'),$body)->assertOk()->json('data');$key=(string)Str::uuid();if($points){$grant=$t->postJson(incentivesUrl('/auth/supervisor-check'),['phone'=>'0710000002','pin'=>'1234','permission'=>'give_discount','operation_id'=>$key,'payload_hash'=>$review['review_hash']])->assertOk()->json('data.approval_token');$body['approval_token']=$grant;}return $t->withHeader('Idempotency-Key',$key)->postJson(incentivesUrl('/sales'),[...$body,'cash_tendered'=>$review['cash_allocated']??$review['total'],'review_hash'=>$review['review_hash']])->assertCreated()->json('data');}
function incentiveReturn($t,array $sale,string $qty='1'):array{$t->withToken($t->alphaCashierToken);$body=['operation_id'=>(string)Str::uuid(),'sale_id'=>$sale['id'],'till_id'=>$t->alphaTill['id'],'reason'=>'Customer return','items'=>[['line_index'=>0,'qty'=>$qty,'disposition'=>'sellable']]];$review=$t->postJson(incentivesUrl('/returns/preview'),$body)->assertOk()->json('data.review_hash');$grant=$t->postJson(incentivesUrl('/auth/supervisor-check'),['phone'=>'0710000002','pin'=>'1234','permission'=>'refund','operation_id'=>$body['operation_id'],'payload_hash'=>$review])->assertOk()->json('data.approval_token');$commit=[...$body,'review_hash'=>$review,'approval_token'=>$grant];$t->withHeader('Idempotency-Key',$body['operation_id'])->postJson(incentivesUrl('/returns'),$commit)->assertCreated();return $commit;}
function incentiveBalance($t):array{return $t->withToken($t->alphaCashierToken)->getJson(incentivesUrl('/customers/'.$t->alphaCustomer->publicId().'/loyalty'))->assertOk()->json('data');}
function incentiveSaleProcess(int $business,int $actor,int $token,array $input,string $key):Closure{return static function()use($business,$actor,$token,$input,$key){if(!app()->environment('testing')||!str_ends_with(config('database.connections.mysql.database'),'_test'))throw new LogicException('Dedicated test database required.');app(TenantContext::class)->set(Business::findOrFail($business));$user=User::findOrFail($actor)->withAccessToken(\App\Models\PersonalAccessToken::findOrFail($token));try{$result=app(\App\Services\SaleService::class)->complete($user,$input,$key);return ['sale_id'=>$result['sale']->publicId()];}catch(\App\Exceptions\ApiException $e){return ['error'=>$e->errorCode];}};}

it('disables earning until configured and keeps historical sale rates immutable with exact replay isolation',function(){
 $sale=incentiveSale($this);expect(incentiveBalance($this)['points'])->toBe(0);$body=configureEarning($this);$this->postJson(incentivesUrl('/incentives/configuration'),$body)->assertOk()->assertJsonPath('data.replayed',true);$this->postJson(incentivesUrl('/incentives/configuration'),[...$body,'reason'=>'Changed'])->assertStatus(409);$this->withToken($this->alphaManagerToken)->getJson(incentivesUrl('/incentives/commissions'))->assertForbidden();$this->withToken($this->betaOwnerToken)->getJson(incentivesUrl('/customers/'.$this->alphaCustomer->publicId().'/loyalty','beta'))->assertNotFound();
 $this->context->run($this->alpha,function(){expect(IncentiveAccount::first()->loyalty_tsh_per_point)->toBeNull();expect(fn()=>IncentiveConfiguration::first()->update(['loyalty_tsh_per_point'=>1]))->toThrow(LogicException::class);});
