 $managerTill=$this->context->run($this->alpha,fn()=>app(TillService::class)->open($this->alphaManager,['operation_id'=>(string)Str::uuid(),'branch_id'=>$this->alphaBranch->publicId(),'opening_float'=>0])['till']);$this->withToken($this->alphaManagerToken);
 foreach([99,1,900]as$amount){$body=['till_id'=>$managerTill['id'],'method'=>'cash','amount'=>$amount,'allocations'=>[['sale_id'=>$sale['id'],'amount'=>$amount]]];$url=incentivesUrl('/customers/'.$this->alphaCustomer->publicId().'/payments');$review=$this->postJson($url.'/preview',$body)->assertOk()->json('data.review_hash');$key=(string)Str::uuid();$commit=[...$body,'review_hash'=>$review];$this->withHeader('Idempotency-Key',$key)->postJson($url,$commit)->assertCreated();$this->postJson($url,$commit)->assertOk()->assertJsonPath('data.replayed',true);}
 expect(incentiveBalance($this)['points'])->toBe(10);$this->context->run($this->alpha,function(){expect(app(IncentiveService::class)->commission($this->alphaCashier)['earned'])->toBe(100);expect(app(IncentiveService::class)->commission($this->alphaManager)['earned'])->toBe(0);});
