it('reverses paid incentives proportionally and carries already-paid commission without blocking refunds',function(){
 configureEarning($this);$sale=incentiveSale($this,'5');$this->withToken($this->alphaOwnerToken);$payout=['operation_id'=>(string)Str::uuid(),'cashier_id'=>$this->alphaCashier->publicId(),'amount'=>500,'paid_on'=>now('Africa/Dar_es_Salaam')->toDateString(),'external_reference'=>'EXTERNAL-COMM-1','external_payment_completed'=>true,'reason'=>'Completed bank payout'];$review=$this->postJson(incentivesUrl('/incentives/commission-payouts/preview'),$payout)->assertOk()->json('data.review_hash');$commit=[...$payout,'review_hash'=>$review];$this->postJson(incentivesUrl('/incentives/commission-payouts'),$commit)->assertCreated()->assertJsonPath('data.external_transfer_executed',false);$this->postJson(incentivesUrl('/incentives/commission-payouts'),$commit)->assertOk()->assertJsonPath('data.replayed',true);
 $returned=incentiveReturn($this,$sale,'2');$this->postJson(incentivesUrl('/returns'),$returned)->assertOk()->assertJsonPath('data.replayed',true);expect(incentiveBalance($this)['points'])->toBe(30);$this->context->run($this->alpha,function(){expect(app(IncentiveService::class)->commission($this->alphaCashier)['refund_carry'])->toBe(200);expect(CommissionPayout::count())->toBe(1);expect(TillCashEntry::where('type','commission_payout')->count())->toBe(0);});
});
it('redeems whole points only with approved checkout and restores them on zero-net returns while carrying reversals',function(){
 configureEarning($this);$original=incentiveSale($this,'10');$redeemed=incentiveSale($this,'1',0,10);expect($redeemed['total'])->toBe(0)->and($redeemed['lines'][0]['loyalty_discount'])->toBe(1000);expect(incentiveBalance($this)['points'])->toBe(90);
